-- Letters module (letter.db)
-- The correspondence register, its workflow and its audit trail.
-- Generated by Migrations/build_module_databases.py --refresh-schema;
-- foreign keys into another module's file are dropped on purpose.

CREATE TABLE letters (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        reference_no TEXT UNIQUE,
        letter_type TEXT NOT NULL
            CHECK (letter_type IN ('official', 'incoming', 'outgoing', 'memo', 'hr', 'finance', 'procurement', 'legal', 'confidential')),
        letter_kind TEXT,
        subject TEXT NOT NULL,
        sender TEXT,
        recipient TEXT,
        letter_date TEXT NOT NULL,
        body TEXT,
        status TEXT NOT NULL DEFAULT 'Draft',
        sender_user_id INTEGER,
        sender_department_id INTEGER,
        recipient_user_id INTEGER,
        recipient_department_id INTEGER,
        sent_at TEXT,
        approved_by INTEGER,
        approved_at TEXT,
        requires_approval INTEGER NOT NULL DEFAULT 0,
        approval_step TEXT,
        approval_depth INTEGER NOT NULL DEFAULT 3,
        created_by INTEGER NOT NULL,
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    , updated_by INTEGER, updated_by_name TEXT);

CREATE TABLE letter_permissions (
        user_id INTEGER NOT NULL,
        permission TEXT NOT NULL,
        allowed INTEGER NOT NULL DEFAULT 0
            CHECK (allowed IN (0, 1)),
        updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        PRIMARY KEY (user_id, permission)
    );

CREATE TABLE letter_category_permissions (
        user_id INTEGER NOT NULL,
        category TEXT NOT NULL,
        allowed INTEGER NOT NULL DEFAULT 0
            CHECK (allowed IN (0, 1)),
        updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        PRIMARY KEY (user_id, category)
    );

CREATE TABLE letter_role_permissions (
        role_key TEXT NOT NULL,
        permission TEXT NOT NULL,
        allowed INTEGER NOT NULL DEFAULT 0
            CHECK (allowed IN (0, 1)),
        updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        PRIMARY KEY (role_key, permission)
    );

CREATE TABLE letter_deliveries (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        letter_id INTEGER NOT NULL REFERENCES letters(id) ON DELETE CASCADE,
        user_id INTEGER,
        department_id INTEGER,
        folder TEXT NOT NULL CHECK (folder IN ('inbox', 'outbox')),
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        CHECK ((user_id IS NULL) <> (department_id IS NULL))
    );

CREATE TABLE letter_reads (
        letter_id INTEGER NOT NULL REFERENCES letters(id) ON DELETE CASCADE,
        user_id INTEGER NOT NULL,
        read_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        PRIMARY KEY (letter_id, user_id)
    );

CREATE TABLE letter_approval_steps (
        letter_id INTEGER NOT NULL REFERENCES letters(id) ON DELETE CASCADE,
        step TEXT NOT NULL CHECK (step IN ('manager', 'director', 'ceo')),
        position INTEGER NOT NULL,
        decision TEXT NOT NULL DEFAULT 'Pending'
            CHECK (decision IN ('Pending', 'Approved', 'Returned')),
        actor_id INTEGER,
        actor_name TEXT,
        comments TEXT NOT NULL DEFAULT '',
        decided_at TEXT,
        PRIMARY KEY (letter_id, step)
    );

CREATE TABLE letter_audit_logs (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL,
        letter_id INTEGER,
        action TEXT NOT NULL,
        details TEXT,
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    );

CREATE INDEX idx_letters_approval_step
        ON letters(status, approval_step);
CREATE INDEX idx_letters_date
        ON letters(letter_date);
CREATE INDEX idx_letters_recipient_department
        ON letters(recipient_department_id);
CREATE INDEX idx_letters_recipient_user
        ON letters(recipient_user_id);
CREATE INDEX idx_letters_reference
        ON letters(reference_no);
CREATE INDEX idx_letters_sender_user
        ON letters(sender_user_id);
CREATE INDEX idx_letters_type_status
        ON letters(letter_type, status);
CREATE UNIQUE INDEX idx_letter_delivery_department
        ON letter_deliveries(letter_id, folder, department_id)
        WHERE department_id IS NOT NULL;
CREATE INDEX idx_letter_delivery_dept
        ON letter_deliveries(folder, department_id);
CREATE INDEX idx_letter_delivery_inbox
        ON letter_deliveries(folder, user_id);
CREATE UNIQUE INDEX idx_letter_delivery_user
        ON letter_deliveries(letter_id, folder, user_id) WHERE user_id IS NOT NULL;
CREATE INDEX idx_letter_audit_created
        ON letter_audit_logs(created_at);
